$beforeJson = shell_exec("git show HEAD:.orbit/sessions/index.json");
if ($beforeJson === null) {
    fwrite(STDERR, "Unable to read HEAD index.\\n");
    exit(2);
}
$before = json_decode($beforeJson, true, 512, JSON_THROW_ON_ERROR);
$after = json_decode(stream_get_contents(STDIN), true, 512, JSON_THROW_ON_ERROR);

$flatten = function (mixed $beforeValue, mixed $afterValue, string $path, array &$changes) use (&$flatten): void {
    if (is_array($beforeValue) && is_array($afterValue)) {
        $keys = array_unique(array_merge(array_keys($beforeValue), array_keys($afterValue)));
        sort($keys);
        foreach ($keys as $key) {
            $childPath = $path === "" ? (string) $key : "{$path}.{$key}";
            $flatten($beforeValue[$key] ?? null, $afterValue[$key] ?? null, $childPath, $changes);
        }
        return;
    }
    if ($beforeValue !== $afterValue) {
        $changes[] = ["path" => $path, "before" => $beforeValue, "after" => $afterValue];
    }
};

$topLevelChanges = [];
foreach (["schema_version", "generated_from", "record_count"] as $key) {
    if (($before[$key] ?? null) !== ($after[$key] ?? null)) {
        $topLevelChanges[] = ["path" => $key, "before" => $before[$key] ?? null, "after" => $after[$key] ?? null];
    }
}

$beforeRecords = [];
foreach ($before["records"] as $record) {
    $beforeRecords[$record["archive"]] = $record;
}
$afterRecords = [];
foreach ($after["records"] as $record) {
    $afterRecords[$record["archive"]] = $record;
}

$recordSetMovement = [
    "removed" => array_values(array_diff(array_keys($beforeRecords), array_keys($afterRecords))),
    "added" => array_values(array_diff(array_keys($afterRecords), array_keys($beforeRecords))),
];
sort($recordSetMovement["removed"]);
sort($recordSetMovement["added"]);

$recordChanges = [];
foreach (array_intersect(array_keys($beforeRecords), array_keys($afterRecords)) as $archive) {
    $changes = [];
    $flatten($beforeRecords[$archive], $afterRecords[$archive], "", $changes);
    if ($changes !== []) {
        $recordChanges[$archive] = $changes;
    }
}
ksort($recordChanges);

$allowedPaths = ["fresh_analyzer_verdict", "fresh_analyzer_verdict_raw"];
$unexpected = [];
foreach ($recordChanges as $archive => $changes) {
    foreach ($changes as $change) {
        if (! in_array($change["path"], $allowedPaths, true)) {
            $unexpected[] = ["archive" => $archive] + $change;
        }
    }
}

$result = [
    "before_record_count" => $before["record_count"],
    "after_record_count" => $after["record_count"],
    "top_level_changes" => $topLevelChanges,
    "record_set_movement" => $recordSetMovement,
    "changed_record_count" => count($recordChanges),
    "changed_records" => $recordChanges,
