];
fwrite(STDOUT, json_encode($result, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR).PHP_EOL);

if (
    $before["record_count"] !== 86
    || $after["record_count"] !== 86
    || $topLevelChanges !== []
    || $recordSetMovement["removed"] !== []
    || $recordSetMovement["added"] !== []
    || $unexpected !== []
) {
    exit(1);
}
